"""Attach masked TRAIN attributes after freezing actual endpoint input features."""
from pathlib import Path
import collections
import numpy as np
from weld_pipeline.sjg_local_runtime_904 import read,write,digest
BASE=Path(__file__).resolve().parents[1]/'server_rebuild/expansion_v1';OUT=BASE/'predicted_endpoint_attribute_labels_v1'
def main():
 feature_root=BASE/'predicted_endpoint_attribute_features_v1';assert read(feature_root/'receipt.json')['status']=='EIGHT_TRAIN_PREDICTED_ENDPOINT_ATTRIBUTE_INPUTS_FROZEN';OUT.mkdir(exist_ok=False);protocol=read(feature_root/'protocol.json');keys=protocol['keys'];write(OUT/'protocol.json',dict(keys=keys,source_endpoint_model_sha256=protocol['endpoint_model_sha256'],require_nonempty_both_endpoint_fit=True,scope='TRAIN reference matching used only to mask attribute supervision after input freeze; ignores type/parent conditions, not full extraction or acceptance',unknown_and_optional_masked=True,fit_calls=0,DEV_reads=0));reports=[]
 for key in keys:
  f=feature_root/key;fr=read(f/'receipt.json');assert digest(f/'features.npy')==fr['features_sha256'] and digest(f/'index.npz')==fr['index_sha256'];index=np.load(f/'index.npz');rows=index['query_rows'];attr=BASE/'query_endpoint_attribute_supervision_v1'/key;ar=read(attr/'receipt.json');assert ar['source_query_receipt_sha256']==fr['query_receipt_sha256'];assert digest(attr/'labels.npz')==ar['labels_sha256'];z=np.load(attr/'labels.npz');assert np.array_equal(z['query_ids'][rows],index['query_ids']);predpath=BASE/'boundary_provenance_batch02_expanded8_v1'/(key+'_training_event_predictions.npz');assert digest(predpath)==fr['prediction_sha256'];pred=np.load(predpath);assert np.array_equal(pred['query_rows'],rows);geometry=pred['nonempty_both_correct'];unique=z['unique_line_owner'][rows];valid=geometry&unique;state=z['state'][rows];numeric=z['exact_mm'][rows];sm=z['state_mask'][rows]&valid[:,None];nm=z['numeric_mask'][rows]&valid[:,None];records=read(BASE/'exhaustive_carrier_supervision_v1/positive_query'/key/'records.json');eligible=valid&sm.any(1);owners=[tuple(records[int(row)]['owners'][0]) if eligible[i] else None for i,row in enumerate(rows)];count=collections.Counter(x for x in owners if x is not None);weight=np.array([1/count[x]/len(count) if x is not None else 0. for x in owners],np.float64);assert not sm[~valid].any() and np.isfinite(numeric[nm]).all();assert abs(weight.sum()-1)<1e-8 if count else weight.sum()==0;dest=OUT/key;dest.mkdir();np.savez(dest/'labels.npz',state=state,exact_mm=numeric,state_mask=sm,numeric_mask=nm,geometry_fit=geometry,unique_owner=unique,row_weight=weight);r=dict(key=key,rows=len(rows),geometry_fit_rows=int(geometry.sum()),supervised_rows=int(eligible.sum()),supervised_children=len(count),known_required_states=int(sm.sum()),exact_required_values=int(nm.sum()),feature_receipt_sha256=digest(f/'receipt.json'),aligned_attribute_receipt_sha256=digest(attr/'receipt.json'),labels_sha256=digest(dest/'labels.npz'),fit_calls=0,DEV_reads=0);write(dest/'receipt.json',r);reports.append(r);print(key,r['supervised_rows'],r['supervised_children'],flush=True)
 write(OUT/'receipt.json',dict(status='EIGHT_TRAIN_PREDICTED_ENDPOINT_ATTRIBUTE_LABELS_READY',cases=reports,fit_calls=0,DEV_reads=0,not_attribute_predictions=True))
if __name__=='__main__':main()
